describe('Recently Searched Terms Suggestions', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display recently searched terms as suggestions when user starts typing', () => {
    // First search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Second search
    cy.get('[data-testid="search-input"]').clear().type('monitor');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Third search
    cy.get('[data-testid="search-input"]').clear().type('keyboard');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Clear results and type again to trigger suggestions
    cy.get('[data-testid="search-results"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Type in search input to trigger suggestions
    cy.get('[data-testid="search-input"]').type('l');

    // Verify suggestions appear
    cy.get('[data-testid="suggestion-list"]').should('be.visible');
    cy.get('[data-testid="suggestion-item"]').should('contain', 'laptop');
    cy.get('[data-testid="suggestion-item"]').should('contain', 'monitor');
    cy.get('[data-testid="suggestion-item"]').should('contain', 'keyboard');

    // Click on a suggestion to populate search input
    cy.get('[data-testid="suggestion-item"]').contains('laptop').click();
    cy.get('[data-testid="search-input"]').should('have.value', 'laptop');
  });

  it('should not display suggestions when search history is empty', () => {
    // Clear any previous search history
    cy.clearLocalStorage('searchHistory');

    // Navigate to search page
    cy.visit('/search');

    // Type in search input without searching
    cy.get('[data-testid="search-input"]').type('test');

    // Verify suggestions do not appear
    cy.get('[data-testid="suggestion-list"]').should('not.exist');

    // Perform a search
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Verify search results are displayed without suggestions
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="suggestion-list"]').should('not.exist');
  });
});
